PYRO_TIMEOUT_TO_WORK = 300
PYRO_TIMEOUT_TO_VALIDATE_CONNECTION = 5
PYRO_LOGLEVEL = 'DEBUG'
PYRO_LOGPATH = 'logs/ta_uepc_pyro.log'
config.ONEWAY_THREADED = True


class PyroClient(UePcSSHControl):
    """PyroClient"""

    # pylint: disable=too-many-instance-attributes, protected-access
    def __init__(self, config, ssh_manager=None):
        """
        :param config:
        :param ssh_manager:
        """
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'PYRO-RPC'})
        self.config = config
        self.local_server_dir = self._default_local_server_dir()
        self.filename_server_runner = '{}/uepc/server_runner.py'.format(plugin_name)
        self.remoteObjName = PYRO_SERVER_OBJ_NAME
        self.pyro_proxes = None
        self.connected = False
        self.os_commands = OsCommands()
        self.shutdown_methods = MethodsQueue()
        self.ue_pc_os = None
        self.robot_output_path = get_robot_variable("OUTPUT_DIR")
        self.notifier = MailSender()
        self.notifier.update_message('Android plugin version: {}'.format(plugin_version))
        self.utils = Utils()
        super(PyroClient, self).__init__(ssh_manager)

    @staticmethod
    def _default_local_server_dir():
        ue_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), 'ue'))
        uepc_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), 'uepc'))
        return [ue_dir, uepc_dir]

    def are_client_and_server_versions_compatible(self, ver, client_ver, do_raise=False):
        """
        Method using after connect to server.
        :param ver: int - version received from server
        :param client_ver: int - version from client
        :return: bool - is server and client version match
        """
        if int(ver) == int(client_ver):
            return True
        self.logger.info(
            "Local (ROBOT PC){} and remote (UEPC){} plugin versions are different\
            Stop python processes and try to delete server files before next execution".format(client_ver, ver))
        if do_raise:
            raise DifferentServerVersionAfterUpdate(ver, client_ver)
        return False

    def get_uepc_platform_with_python(self, hostname):
        """
        Returns os version based on sys.platform output provided
        :param hostname:
        :return:
        """
        cmd_template = self.os_commands.get_platform_cmd_template()
        cmd = cmd_template.format(python_path=self.config['server_python'])
        output_lines = self.ssh_manager.run_cmd_and_get_output_lines(cmd, hostname, as_string=False, timeout=40,
                                                                     reuse_connection=True)
        for line in output_lines:
            if any(platform_string in line for platform_string in ['lin', 'win']):
                return line
        raise UnexpectedCmdResultException('Unable to check UE PC platform.\nOutput from \"{}\": {}'.format(cmd, output_lines))

    def _new_ssh_manager(self):
        return SshManager()

    def connect(self):
        """
        Connects to server.
        If server will be dead, make him alive.
        If server will be out date, make him up-to-date.
        :return: None
        """
        config.SOCK_REUSE = True
        ue_pc_ip = self.config['ue_pc_ip']
        self._check_if_ssh_manager()
        self.ssh_manager.register(hostname=ue_pc_ip, username=self.config['login'], password=self.config['password'])
        self._set_uepc_os_version(ue_pc_ip)
        self.kill_remote_process_by_listening_port(self.config['pyro_port'], self.ssh_manager, ue_pc_ip, self.ue_pc_os)
        self.logger.debug('Starting connection to pyro server')
        self.notifier.update_message('Starting connection to pyro server')

        if self._should_turn_on_off_firewall_on_uepc():
            self._turn_off_on_firewall_on_uepc(ue_pc_ip)
        if self._should_kill_any_processes_on_uepc():
            self.kill_processes_on_uepc(ue_pc_ip)
        if self._should_clear_server_logs():
            self._close_log_handlers_if_connected()
            self._remove_files_and_verify(ue_pc_ip, "rm -rf {}/logs/*".format(self.config['server_dir']),
                                          self.ue_pc_os)
        if self._should_clear_server_files():
            self._remove_files_and_verify(ue_pc_ip, "rm -rf {}/{}/".format(self.config['server_dir'], plugin_name),
                                          self.ue_pc_os)
        else:
            self._start_server_runner(ue_pc_ip, await_welcome_msg=False)
            connection_success, version_match = self._try_pyro_connect_with_version_verify()

            if connection_success and version_match:
                self.logger.debug('pyro server version valid and connection success, finish method PyroClient::connect()')
                return

        self._remove_files_and_verify(ue_pc_ip, "rm -rf {}/{}/".format(self.config['server_dir'], plugin_name),
                                      self.ue_pc_os)
        self.make_server_directory_structure_on_uepc(ue_pc_ip)
        self._transfer_folder_to_remote_ssh_host(ue_pc_ip)
        self.decompress_zip_server_directory_files_on_ue_pc(ue_pc_ip, self.ue_pc_os)
        self.set_permissions_of_server_directory_on_ue_pc(ue_pc_ip)
        self._start_server_runner(ue_pc_ip)
        self._try_pyro_connect_with_version_verify(do_raise=True)

    def make_server_directory_structure_on_uepc(self, ue_pc_ip):
        """
        Creates server directory structure on UE PC.
        The main server folders based on server_dir from yaml: server_dir itself, server_dir/logs + server_dir/ue
        :param ue_pc_ip:
        :return:
        """
        server_dir = self.config['server_dir']

        make_root_folders_cmd = 'mkdir {server_dir}; mkdir {server_dir}/logs'.format(server_dir=server_dir)
        self.logger.debug('create directory by command:{}'.format(make_root_folders_cmd))
        self.ssh_manager.run_cmd_and_get_output_lines(make_root_folders_cmd, ue_pc_ip, as_string=True,
                                                      reuse_connection=True)

        commands = ['cd {}'.format(server_dir),
                    'mkdir {}/{}'.format(server_dir, plugin_name),
                    'mkdir {}/{}/ue'.format(server_dir, plugin_name),
                    'mkdir {}/{}/uepc'.format(server_dir, plugin_name),
                    'touch {}/{}/__init__.py'.format(server_dir, plugin_name),
                    'touch {}/{}/ue/__init__.py'.format(server_dir, plugin_name),
                    'touch {}/{}/uepc/__init__.py'.format(server_dir, plugin_name)]

        for cmd in commands:
            self.ssh_manager.run_cmd_and_get_output_lines(cmd, ue_pc_ip, as_string=True, reuse_connection=True)

    def set_permissions_of_server_directory_on_ue_pc(self, ue_pc_ip):
        """
        Change permissions to directory path UE PC.
        The main server folders based on server_dir from yaml: server_dir itself, server_dir/logs + server_dir/ue
        :param ue_pc_ip:
        :param path:
        :return:
        """
        path = self.config['server_dir']
        self.set_permissions_to_path_on_uepc(path, ue_pc_ip, reuse_connection=True)

    def decompress_zip_server_directory_files_on_ue_pc(self, ue_pc_ip, os_version):
        """
        Change permissions to directory path UE PC.
        The main server folders based on server_dir from yaml: server_dir itself, server_dir/logs + server_dir/ue
        :param ue_pc_ip:
        :param path:
        :param os_version:
        :return:
        """
        python_path = self.config['server_python']
        for i in self.local_server_dir:
            subdir = os.path.basename(os.path.normpath(i))
            path = '{}/{}/{}'.format(self.config['server_dir'], plugin_name, subdir)
            file_name = subdir + '.zip'
            self.decompress_zip_file_on_uepc(python_path, path, file_name, ue_pc_ip,
                                             reuse_connection=True)
        self.veify_server_runner_exists(os_version=os_version,
                                        ue_pc_ip=ue_pc_ip,
                                        path='{}/{}/{}'.format(self.config['server_dir'], plugin_name, 'uepc'))

    def veify_server_runner_exists(self, os_version, ue_pc_ip, path, file_name='server_runner.py', timeout=15):
        start_time = time.time()
        while time.time() < start_time + timeout:
            if self.verify_file_exists(os_version=os_version,
                                       ue_pc_ip=ue_pc_ip,
                                       path=path,
                                       file_name=file_name):
                return
        self.logger.info('Verification was failing within {} second. '
                         'Running last chance verification with different verification method for windows'.format(timeout))
        # Verification on some windows ue pc's was not working with 'findstr' and 'grep' should work instead
        if self.verify_file_exists(os_version=os_version,
                                   ue_pc_ip=ue_pc_ip,
                                   path=path,
                                   file_name=file_name,
                                   find_method='grep'):
            return
        raise Exception("Cannot find {} in {} on uepc: {} with {} os for {} seconds".format(file_name,
                                                                                            path,
                                                                                            ue_pc_ip,
                                                                                            os_version,
                                                                                            timeout))

    def set_permissions_to_path_on_uepc(self, path, ue_pc_ip, reuse_connection=False):
        """
        Change permission to given path on remote PC.
        :param path:
        :param ue_pc_ip:
        :param reuse_connection: bool
        """
        ue_pc_os = self.ue_pc_os
        try:
            self.set_permissions_to_remote_path(ue_pc_ip, ue_pc_os, path, reuse_connection=reuse_connection)
        except Exception as e:
            self.logger.debug('Failed to change permissions: {}'.format(e))

    def decompress_zip_file_on_uepc(self, python_path, path, file_name, ue_pc_ip,
                                    reuse_connection=False):
        """
        Decompress zip file on remote PC.
        :param python_path: string
        :param path: string
        :param file_name: string
        :param ue_pc_ip: string
        :param reuse_connection: bool
        """
        ue_pc_os = self.ue_pc_os
        path = convert_cygwin_path_to_windows_path(path)
        try:
            self.decompress_remote_zip_file(ue_pc_ip, ue_pc_os, python_path, path, file_name,
                                            reuse_connection=reuse_connection)
        except Exception as e:
            self.logger.debug('Failed to decompress files: {}'.format(e))

    def kill_processes_on_uepc(self, ue_pc_ip):
        """Kill processes based on phrases defined in processes_to_kill yaml parameter"""
        for process in self.config['processes_to_kill']:
            self.kill_remote_process_with_phrase(ue_pc_ip, self.ue_pc_os, process, reuse_connection=True)

    def _start_server_runner(self, ue_pc_ip, await_welcome_msg=True, timeout=30):
        self.logger.debug("Starting server runner at _start_server_runner")
        reader = self.ssh_manager.run_cmd_and_get_non_blocking_reader(self._get_run_server_cmd(), ue_pc_ip)
        self.logger.debug("Starting pyro server_runner with cmd: {}.".format(self._get_run_server_cmd()))
        if await_welcome_msg:
            self._await_welcome_msg_from_server(reader, ue_pc_ip, timeout=timeout)

    def _should_clear_server_files(self):
        return any([self.config.get('clear_server_files') == value for value in ['yes', True]])

    def _should_clear_server_logs(self):
        return any([self.config.get('clear_logs') == value for value in ['yes', True]])

    def _should_kill_any_processes_on_uepc(self):
        return self.config.get('processes_to_kill', [])

    def _close_log_handlers_if_connected(self):
        if self.connected:
            with Proxy(self._get_pyro_uri()) as p:
                p.close_log_handlers()

    def _should_turn_on_off_firewall_on_uepc(self):
        if self.config.get('turn_off_on_firewall', None) == 'yes':
            if self.ue_pc_os != 'windows':
                self.logger.warning("Changing firewall settings is only supported on win platform!")
                return False
            return True
        return False

    def _turn_off_on_firewall_on_uepc(self, ue_pc_ip):
        self._turn_off_firewall_on_uepc(ue_pc_ip, self.ue_pc_os)
        self.shutdown_methods.add_method(self._turn_on_firewall_on_uepc, ue_pc_ip, self.ue_pc_os)

    def _transfer_folder_to_remote_ssh_host(self, ue_pc_ip):
        self.logger.debug('transfer folder:{} to remote:{}:/{}'.format(self.local_server_dir, ue_pc_ip, self.config['server_dir']))
        server_dir = self.config['server_dir']
        self.ssh_manager.transfer_folder_to_remote_ssh_host(ue_pc_ip, server_dir, self.local_server_dir,
                                                            reuse_connection=True)
        self.logger.debug('pyro server version valid, no need to transfer folder on UE PC')

    def _check_if_ssh_manager(self):
        self.ssh_manager = self.ssh_manager or self._new_ssh_manager()
        if not self.ssh_manager:
            self.ssh_manager = SshManager()
        if not self.ssh_manager:
            raise Exception("Could not establish SSH connection.")

    def _await_welcome_msg_from_server(self, reader, ue_pc_ip, do_raise=False, timeout=30):
        expect_welcome_msg = 'ue_pc_pyro_server_started'
        full_result = []
        for _ in range(3):
            try:
                is_welcome_msg_received, result = self._check_if_expected_msg_received(reader, expect_welcome_msg, timeout=timeout)
                full_result += result
                if is_welcome_msg_received:
                    self.logger.info("Welcome msg line received from pyro server")
                    return
            except socket.timeout:
                self.logger.debug("Socket timeout. Retrying to read from server")
        raise NoWelcomeMessageFromServer(full_result, expect_welcome_msg, ue_pc_ip)

    def _check_if_expected_msg_received(self, reader, expect_msg, timeout=30):
        end_time = time.time() + timeout
        result = []
        while not reader.is_finish() and time.time() <= end_time:
            if not reader.has_line_without_blocking():
                self.logger.debug('Waiting for cmd output: {}'.format(time.time()))
                time.sleep(1)
                continue
            lines = reader.read_lines()
            result += lines
            if expect_msg in result:
                self.logger.debug('Expected msg {} received'.format(expect_msg))
                return (True, lines)
            self.logger.debug('Expected msg {} not received yet, waiting...'.format(expect_msg))
            time.sleep(0.5)
        self.logger.debug('Expected msg {} not received. Cmd output: {}'.format(expect_msg, result))
        return (False, result)

    def _get_uepc_os_version(self, ue_pc_ip):
        if self.ue_pc_os:
            return self.ue_pc_os
        ue_pc_platform = self.get_uepc_platform_with_python(ue_pc_ip)
        self.ue_pc_os = self.os_commands.get_os_version(ue_pc_platform)
        return self.ue_pc_os

    def _set_uepc_os_version(self, ue_pc_ip):
        self.ue_pc_os = self._get_uepc_os_version(ue_pc_ip)
        self.notifier.update_message('UE PC OS: {}'.format(self.ue_pc_os))

    def _try_pyro_connect_with_version_verify(self, do_raise=False, timeout=10):
        end_time = time.time() + timeout
        while not self._is_connected_to_server() and time.time() < end_time:
            try:
                config.COMMTIMEOUT = PYRO_TIMEOUT_TO_VALIDATE_CONNECTION
                self.logger.debug("try connect to pyro_server to validate it's version, do_raise=" + str(do_raise))
                with Proxy(self._get_pyro_uri()) as p:
                    time.sleep(2)
                    ver = p.get_version()  # invoke anything to test connection
                    self.logger.info("Remote server version (UEPC): {}".format(ver))
                    self.logger.info("Local plugin android version (ROBOT PC): {}".format(plugin_version))
                    self.logger.info("Local ute_ue version (ROBOT PC): {}".format(ute_ue_version))
                    is_version_match = self.are_client_and_server_versions_compatible(ver, plugin_version.replace('.', ''), do_raise)

                config.COMMTIMEOUT = PYRO_TIMEOUT_TO_WORK
                self.logger.debug("register 'keep_reservation' pyro_proxy")
                self.pyro_proxes = {'keep_reservation': Proxy(self._get_pyro_uri())}
                self.connected = True
                self.logger.debug("Successfully connected to pyro server.")
                return self.connected, is_version_match
            except (errors.CommunicationError, errors.PyroError) as e:
                self._raise_if_need_after_try_to_connect(do_raise, e)
                continue
        return False, False

    def _raise_if_need_after_try_to_connect(self, do_raise, e):
        if do_raise:
            self.logger.exception("Can't connect directly to pyro server, do_raise=" + str(do_raise), exc_info=True)
            to_raise = CannotConnectToPyroServerException("{}: {}".format(e.__class__, e))
            six.reraise(to_raise.__class__, to_raise, sys.exc_info()[2])
        else:
            self.logger.debug("Unable to connect to pyro server. {}: {}.\nRetrying...".format(e.__class__, e), exc_info=True)

    def _get_pyro_uri(self):
        result = 'PYRO:{}@{}:{}'.format(self.remoteObjName, self.config['ue_pc_ip'], self.config['pyro_port'])
        self.logger.debug("pyro uri = " + result)
        return result

    def _get_run_server_cmd(self):
        cmd_base = "cd {server_dir} ; export PYTHONPATH='.'; export PYRO_LOGLEVEL='{pyro_loglevel}'; export PYRO_LOGFILE='{pyro_logpath}'; " \
                   "{server_python} -u -i {filename_server_runner} {ue_pc_ip} {pyro_port} {login} {password} 2>&1"
        cmd = cmd_base.format(server_dir=self.config['server_dir'],
                              server_python=self.config['server_python'],
                              filename_server_runner=self.filename_server_runner,
                              ue_pc_ip=self.config['ue_pc_ip'],
                              pyro_port=self.config['pyro_port'],
                              login=self.config['login'],
                              password=self.config['password'],
                              pyro_loglevel=PYRO_LOGLEVEL,
                              pyro_logpath=PYRO_LOGPATH)
        self.logger.debug('run server: ' + cmd)
        return cmd

    def _get_remove_plugin_dir_cmd(self):
        return "rm -r {}/{}/".format(self.config['server_dir'], plugin_name)

    def set_local_server_dir(self, local_server_dir):
        """
        Changes dir on local machine where are kept files to update server.
        :param local_server_dir:
        """
        self.local_server_dir = local_server_dir

    def run_on_pool_controller(self, *args, **kwargs):
        """
        Proxy method call on server.
        :param args:
        :param kwargs:
        :return: response from server.
        """
        return self.run_on_pool_controller_on_specific_pyro_thread('default-pyro-proxy', *args, **kwargs)

    def run_on_pool_controller_on_specific_pyro_thread(self, pyro_proxy_name, *args, **kwargs):
        """
        Proxy method call on server.
        :param pyro_proxy_name:
        :param args:
        :param kwargs:
        :return:
        """
        self._make_sure_connected_to_pyro_server()
        if pyro_proxy_name not in self.pyro_proxes:
            self.logger.debug("register new pyro_proxy with name in inner dict: \"{}\"".format(pyro_proxy_name))
            self.pyro_proxes[pyro_proxy_name] = Proxy(self._get_pyro_uri())

        kwargs = self._set_pyro_proxy_timeout_if_given_and_return_kwargs(pyro_proxy_name, **kwargs)
        try:
            result = self.pyro_proxes[pyro_proxy_name].run_on_pool_controller(*args, **kwargs)
        except TimeoutError as e:
            self.logger.error(
                'During execution of remote call a timeout has occured. Pyro proxy {} called with:\nargs={}\nkwargs={}'
                .format(pyro_proxy_name, args, kwargs))
            self.logger.error(getattr(e, 'message', str(e)))
            pyro_error = PyroTimeoutError(
                'During execution of remote call a timeout has occured. Pyro proxy {} called with:\nargs={}\nkwargs={}'
                .format(pyro_proxy_name, args, kwargs))
            raise pyro_error
        return result

    @oneway
    def oneway_run_on_pool_controller_on_specific_pyro_thread(self, pyro_proxy_name, *args, **kwargs):
        """
        Proxy method call on server. It uses oneway method that doesnt wait for response.
        :param args:
        :param kwargs:
        :return: response from server.
        """
        self._make_sure_connected_to_pyro_server()
        if pyro_proxy_name not in self.pyro_proxes:
            self.logger.debug("register new pyro_proxy with name in inner dict: \"{}\"".format(pyro_proxy_name))
            self.pyro_proxes[pyro_proxy_name] = Proxy(self._get_pyro_uri())
        result = self.pyro_proxes[pyro_proxy_name].oneway_run_on_pool_controller(*args, **kwargs)
        return result

    def _make_sure_connected_to_pyro_server(self):
        if self.pyro_proxes is None:
            raise NotConnectedToUePcServer()
        if not self._is_connected_to_server():
            self.connect()

    def _set_pyro_proxy_timeout_if_given_and_return_kwargs(self, pyro_proxy_name, **kwargs):
        pyro_timeout = kwargs.get('pyro_timeout')
        kwargs.pop('pyro_timeout', None)
        if pyro_timeout:
            self.pyro_proxes[pyro_proxy_name]._pyroTimeout = float(pyro_timeout)
        else:
            self.pyro_proxes[pyro_proxy_name]._pyroTimeout = PYRO_TIMEOUT_TO_WORK
        return kwargs

    def disconnect_from_pyro_server(self):
        """
        Disconnects all connted pyro proxes (threads on pyro server)
        :return:
        """
        for proxy_name, proxy_instance in self.pyro_proxes.items():
            self.logger.debug('Releasing {} pyro thread'.format(proxy_name))
            proxy_instance._pyroRelease()

    def _is_connected_to_server(self):
        return self.connected

    def download_uepc_log(self):
        """Downloads UE PC log from pyro_server/logs at UE PC into Robot Framework test output directory"""
        try:
            self._get_uepc_log()
        except TransferTimeExceeded:
            self.logger.debug("UE PC log download time exceeded!")

    def _get_uepc_log(self):
        if self.robot_output_path is None:
            return
        local_uepc_log_path = "{}/{}".format(self.robot_output_path, UEPC_LOGFILE_NAME)
        remote_uepc_log_path = "{}/logs/{}".format(self.config["server_dir"], UEPC_LOGFILE_NAME)
        self.get_file_from_uepc(remote_uepc_log_path, local_uepc_log_path)

    def get_file_from_uepc(self, path_to_file_on_uepc, path_to_save_file_on_robot_pc):
        """Downloads files from uepc to desired path"""
        is_downloaded = self.ssh_manager.transfer_files_from_remote_ssh_host(self.config['ue_pc_ip'], [path_to_file_on_uepc],
                                                                             path_to_save_file_on_robot_pc)
        if is_downloaded:
            self.logger.debug("UE PC file '{}' downloaded to {}".format(path_to_file_on_uepc, path_to_save_file_on_robot_pc))
            return is_downloaded
        self.logger.debug("Failed to download {} file.".format(path_to_file_on_uepc))
        return is_downloaded

    def push_file_to_uepc(self, path_to_file_on_robot_vm, path_to_remote_file):
        """
        Sends file from robot machine to UEPC
        :param path_to_file_on_robot_vm: string containing path to file on robot machine
        :param path_to_remote_file: string pointing to path on UEPC where to save file. Must contain file name
        :return:
        """
        self.ssh_manager.transfer_file_to_remote_ssh_host(self.config['ue_pc_ip'], path_to_file_on_robot_vm, path_to_remote_file)

    def shutdown(self):
        """
        Shutdowns pyro client.
        :return:
        """
        self.logger.debug('Shutting down the pyro server')
        self.shutdown_methods.run_methods()
        self.pyro_proxes.clear()
        self.download_uepc_log()
        with Proxy(self._get_pyro_uri()) as p:
            self.logger.debug("Pyro proxes before stop server: {}".format(self.pyro_proxes))
            p.stop_server()
            self.logger.debug("Pyro server should not be running now.")
        self.kill_remote_process_by_listening_port(self.config['pyro_port'],
                                                   self.ssh_manager, self.config['ue_pc_ip'], self.ue_pc_os)
        self.logger.debug("Trying to kill processes running with pyro_port from yaml.")
        self.ssh_manager.close_all_ssh_connections()
        self.connected = False
        self.notifier.update_message('Pyro server should not be running now.')
        try:
            self.notifier.send_mail()
        except Exception as e:
            self.logger.error('Could not send notification: {}.'.format(e))


def convert_cygwin_path_to_windows_path(path):
    """
    Convert cygwin style path into windows style path
    :param path: string containing path
    :return:
    """
    if 'cygdrive' in path:
        path_list = path.split("/")
        drive = '{}{}'.format(path_list[2], ":/")
        path = '{}{}'.format(drive, '/'.join(path_list[3:]))
    return path
